  $x${"story_ar":"اعتمدت أمانة المنطقة مشروع مركز خدمات رقمي يختصر زمن رخص البناء. أمامك أنشطة المرحلة القادمة بمددها، ومعلمان مدتهما صفر: بوابة اعتماد التصميم، ومعلم الإطلاق. وكتب الفريق قواعد التتابع بلغة العمل، ومهمتك تحويلها إلى اعتماديات يحسب منها الجدول.","role_ar":"مدير مشروع مركز الخدمات الرقمي","closing_ar":"الجدول لا يقول متى ننتهي فقط، بل أين يجب أن تنظر. المسار الحرج يُتابع أسبوعيًا، والنشاط الذي له فائض يُتابع حين يستهلك فائضه، وكل تأخير على المسار الحرج قرار يُرفع لا تاريخ يُعدّل.","meters":[],"steps":[{"type":"schedule","title_ar":"حوّل القواعد إلى اعتماديات","prompt_ar":"لكل قاعدة أضف اعتمادية بنوعها الصحيح، والإزاحة بالأيام إن ذكرتها القاعدة. المخطط يُرسم مع كل إضافة.","context_ar":"","why_ar":"قاعدة \"يبدأ بعد عشرة أيام من بدء\" اعتمادية بدء ← بدء بإزاحة 10، و\"لا ينتهي قبل خمسة أيام من انتهاء\" انتهاء ← انتهاء بإزاحة 5، ومعًا يصنعان التداخل بين البناء والتكامل. وقاعدة التدريب نادرة: بدء التشغيل يقيد انتهاء التدريب، فهي بدء ← انتهاء من التشغيل إلى التدريب. المدة 90 يومًا، والمسار الحرج: التصميم، فالبوابة، فالبناء، فالتكامل، فالتشغيل التجريبي، فالإطلاق.","weight":3,"tasks":[{"id":"design","label":"التصميم التفصيلي","dur":20},{"id":"gate","label":"بوابة اعتماد التصميم","dur":0},{"id":"build","label":"بناء المنصة","dur":40},{"id":"integ","label":"التكامل مع نظام الرخص","dur":25},{"id":"content","label":"إعداد أدلة الخدمة","dur":20},{"id":"train","label":"تدريب موظفي المركز","dur":15},{"id":"pilot","label":"التشغيل التجريبي","dur":20},{"id":"launch","label":"معلم الإطلاق","dur":0}],"expected":[{"from":"design","to":"gate","type":"FS","lag":0},{"from":"gate","to":"build","type":"FS","lag":0},{"from":"gate","to":"content","type":"FS","lag":0},{"from":"gate","to":"train","type":"FS","lag":0},{"from":"build","to":"integ","type":"SS","lag":10},{"from":"build","to":"integ","type":"FF","lag":5},{"from":"integ","to":"pilot","type":"FS","lag":0},{"from":"content","to":"pilot","type":"FS","lag":0},{"from":"pilot","to":"train","type":"SF","lag":0},{"from":"pilot","to":"launch","type":"FS","lag":5}],"rules_ar":["لا تُعقد بوابة اعتماد التصميم قبل اكتمال التصميم التفصيلي.","لا يبدأ بناء المنصة إلا بعد عبور البوابة.","يبدأ إعداد أدلة الخدمة بعد عبور البوابة، وكذلك تدريب الموظفين.","يبدأ التكامل بعد عشرة أيام من بدء البناء، حين تجهز الواجهات الأولى.","لا ينتهي التكامل قبل مرور خمسة أيام على انتهاء البناء، لاختبار آخر نسخة.","لا يبدأ التشغيل التجريبي قبل انتهاء التكامل وانتهاء أدلة الخدمة.","حتى لا ينسى الموظفون ما تعلموه، لا ينتهي التدريب قبل أن يبدأ التشغيل التجريبي.","يُعلن الإطلاق بعد خمسة أيام من انتهاء التشغيل التجريبي لمعالجة الملاحظات."]},{"type":"classify","title_ar":"من يُتابع أسبوعيًا؟","prompt_ar":"بعد حساب الجدول الصحيح، صنّف كل نشاط بحسب طريقة متابعته.","context_ar":"","why_ar":"الفائض الصفري هو ما يجعل النشاط حرجًا: أي تأخير فيه يؤخر الإطلاق مباشرة.","weight":1,"bins":[{"id":"critical","label":"على المسار الحرج: يُتابع أسبوعيًا"},{"id":"float","label":"له فائض: يُتابع حين يستهلك فائضه"}],"items":[{"id":"design","label":"التصميم التفصيلي","bin":"critical"},{"id":"build","label":"بناء المنصة","bin":"critical"},{"id":"integ","label":"التكامل مع نظام الرخص","bin":"critical"},{"id":"pilot","label":"التشغيل التجريبي","bin":"critical"},{"id":"content","label":"إعداد أدلة الخدمة","bin":"float","note_ar":"تنتهي الأدلة في اليوم 40 والتشغيل يبدأ في اليوم 65: فائضها 25 يومًا."},{"id":"train","label":"تدريب موظفي المركز","bin":"float","note_ar":"التدريب مقيد بأن ينتهي بعد بدء التشغيل، ولا يقيد شيئًا بعده، ففائضه 25 يومًا."}]},{"type":"choice","title_ar":"تأخر خارج المسار الحرج","prompt_ar":"أبلغك فريق المحتوى أن أدلة الخدمة ستتأخر 15 يومًا بسبب مراجعة قانونية. ما أثر ذلك على معلم الإطلاق؟","context_ar":"","why_ar":"الفائض الزمني ما يحتمله النشاط من تأخير دون أن يمس المعلم. التأخير هنا 15 من فائض 25.","weight":1,"options":[{"id":"none","label":"لا أثر على الإطلاق، لكن الفائض ينخفض إلى 10 أيام فأضعه تحت المتابعة","score":4,"feedback_ar":"صحيح. التأخير أقل من الفائض (25 يومًا)، فلا يمس المعلم، لكنه يستهلك هامش الأمان.","then_ar":""},{"id":"delay15","label":"يتأخر الإطلاق 15 يومًا","score":0,"feedback_ar":"الأدلة ليست على المسار الحرج؛ فائضها يمتص التأخير كله.","then_ar":""},{"id":"crash","label":"نضغط التكامل 15 يومًا لتعويض التأخير","score":1,"feedback_ar":"تضغط نشاطًا حرجًا بكلفة لتعويض تأخير لا يحتاج تعويضًا.","then_ar":""}]},{"type":"choice","title_ar":"تأخر على المسار الحرج","prompt_ar":"ثم أبلغك قائد التطوير أن التكامل سيتأخر 10 أيام، وحدود التحمل المتفق عليها مع الراعي أسبوع واحد. ماذا تفعل؟","context_ar":"","why_ar":"المعلم على المسار الحرج: تأخير التكامل يؤخره يومًا بيوم. وحدود التحمل تحدد ما تديره أنت وما يُرفع.","weight":1,"options":[{"id":"escalate","label":"أحسب أثره: الإطلاق يتأخر 10 أيام، وهذا يتجاوز حدود التحمل، فأرفعه لصاحب القرار ومعه خيارات للتعويض","score":4,"feedback_ar":"هذه الإدارة بالاستثناء: ما تجاوز حدود التحمل يُصعّد بمعلومات مكتملة.","then_ar":""},{"id":"float","label":"أعوّضه من فائض التدريب","score":0,"feedback_ar":"فائض التدريب لا ينقل إلى نشاط آخر؛ التكامل حرج وكل يوم فيه يوم في الإطلاق.","then_ar":""},{"id":"shrink","label":"أقلص التشغيل التجريبي 10 أيام دون الرجوع لأحد","score":1,"feedback_ar":"قد يكون خيارًا صالحًا، لكنه يمس الجودة والمخاطر، فهو قرار صاحب الصلاحية لا قرارك وحدك.","then_ar":""},{"id":"quiet","label":"أعدّل تاريخ الإطلاق في الجدول وأخبرهم في التقرير الشهري","score":0,"feedback_ar":"تعديل التاريخ بصمت يحول المعلم إلى تاريخ يُرجى، ويفقدك ثقة الراعي حين يكتشفه.","then_ar":""}]}]}$x$::jsonb
) on conflict (key) do nothing;

insert into leaders.lab_items (key, kind, dimension, chapter_key, sort, min_level, minutes, points, title_ar, summary_ar, spec) values (
  $x$risk-register$x$, $x$tool$x$, $x$milestone$x$, $x$ch4$x$, 2, $x$beginner$x$, 12, 35,
