  $x${"story_ar":"وصلتك هذا الأسبوع قائمة مختلطة من الفريق: أمور حدثت، وأمور قد تحدث، وطلبات تغيير. والسجل الذي لا يفرق بينها لا يصلح لقرار.","role_ar":"مدير مشروع مركز الخدمات الرقمي","closing_ar":"الخطر يُسجل وتُعد له استجابة قبل وقوعه، والقضية تحتاج قرارًا الآن، والتغيير يمر بطلب موثق يُقاس أثره على خط الأساس. وحين يقع خطر مسجل تُفعّل خطته المعدة ولا تُرتجل خطة جديدة.","meters":[],"steps":[{"type":"classify","title_ar":"خطر أم قضية أم تغيير؟","prompt_ar":"صنّف كل بند في سجله الصحيح.","context_ar":"","why_ar":"الفرق في الزمن: الخطر في المستقبل وله استجابة معدة، والقضية في الحاضر ولها قرار، والتغيير طلب على خط الأساس المعتمد.","weight":1,"bins":[{"id":"risk","label":"خطر: محتمل لم يقع"},{"id":"issue","label":"قضية: وقعت وتحتاج قرارًا"},{"id":"change","label":"طلب تغيير: يمس نطاقًا أو موعدًا أو تكلفة معتمدة"}],"items":[{"id":"vendor","label":"قد يتأخر المورد في تسليم واجهات الربط لانشغاله بمشروع آخر","bin":"risk"},{"id":"server","label":"تعطل خادم الاختبار منذ أمس وتوقف فريق التكامل","bin":"issue"},{"id":"demolition","label":"طلب وكيل الأمانة إضافة خدمة رخص الهدم إلى الإطلاق الأول","bin":"change"},{"id":"resist","label":"قد يرفض موظفو الفروع النظام لأنه يغير إجراءاتهم","bin":"risk"},{"id":"lead","label":"استقال قائد فريق التطوير اليوم","bin":"issue"},{"id":"payment","label":"طلبت الإدارة المالية تغيير بوابة الدفع المعتمدة في التصميم","bin":"change"},{"id":"policy","label":"قد يتأخر اعتماد سياسة البيانات من إدارة الأمن السيبراني","bin":"risk"}]},{"type":"plot","title_ar":"خريطة الاحتمال والأثر","prompt_ar":"ضع كل خطر في خانته بحسب المعلومات المرفقة به.","context_ar":"تأخر المورد: تأخر في آخر مشروعين معنا، وواجهاته على المسار الحرج. رفض الموظفين: حدث جزئيًا في تجربة مشابهة، وإن وقع تفشل الخدمة كلها. سياسة البيانات: الإدارة بطيئة عادة، والتأخير يؤخر الربط أسبوعين يمكن امتصاص بعضهما. انقطاع الكهرباء يوم الإطلاق: نادر جدًا ويوقف المركز يومًا. ارتفاع سعر رخصة البرمجيات 2%: يحدث سنويًا وأثره ضئيل على الميزانية.","why_ar":"الخانة تحدد الاهتمام: المرتفع في الاثنين يُدار أسبوعيًا بمالك واستجابة، والمنخفض فيهما يُقبل ويُراقب.","weight":1,"size":3,"x_ar":["احتمال منخفض","احتمال متوسط","احتمال مرتفع"],"y_ar":["أثر منخفض","أثر متوسط","أثر مرتفع"],"items":[{"id":"vendor","label":"تأخر المورد","x":2,"y":2},{"id":"resist","label":"رفض الموظفين للنظام","x":1,"y":2},{"id":"policy","label":"تأخر سياسة البيانات","x":1,"y":1},{"id":"power","label":"انقطاع الكهرباء يوم الإطلاق","x":0,"y":1},{"id":"license","label":"ارتفاع سعر الرخصة 2%","x":2,"y":0}]},{"type":"match","title_ar":"استجابة كل خطر","prompt_ar":"اختر لكل خطر استراتيجية الاستجابة التي يصفها الإجراء المقترح.","context_ar":"","why_ar":"التجنب يغير الخطة فيزول الخطر، والنقل يحمّل أثره طرفًا آخر، والتخفيف يقلل احتماله أو أثره، والقبول قرار واعٍ بتحمله.","weight":1,"left":[{"id":"scope","label":"خدمة رخص الهدم معقدة وقد تؤخر الإطلاق: نخرجها من الإصدار الأول","match":"avoid"},{"id":"hosting","label":"عطل مركز البيانات: اتفاقية مستوى خدمة بتعويض مالي مع مزود الاستضافة","match":"transfer","note_ar":"التعويض التعاقدي ينقل الأثر المالي لطرف آخر، ولا يمنع العطل."},{"id":"policy","label":"تأخر سياسة البيانات: إشراك الأمن السيبراني في ورشة التصميم من الأسبوع الأول","match":"mitigate"},{"id":"license","label":"ارتفاع سعر الرخصة 2%: نتركه ونراقبه في المراجعة الربعية","match":"accept"}],"right":[{"id":"avoid","label":"تجنب"},{"id":"transfer","label":"نقل"},{"id":"mitigate","label":"تخفيف"},{"id":"accept","label":"قبول"}]},{"type":"choice","title_ar":"وقع الخطر المسجل","prompt_ar":"أبلغك المورد أن واجهات الربط ستتأخر ثلاثة أسابيع. الخطر مسجل في السجل ومعه خطة استجابة معدة. ماذا تفعل الآن؟","context_ar":"","why_ar":"حين يقع خطر مسجل يصبح قضية: تُفعّل استجابته المعدة ويُبلغ صاحب القرار.","weight":1,"options":[{"id":"activate","label":"أفعّل خطة الاستجابة المعدة، وأنقل البند إلى سجل القضايا، وأبلغ صاحب القرار بالأثر على المعلم","score":4,"feedback_ar":"هذا ما أُعد السجل لأجله.","then_ar":""},{"id":"meeting","label":"أعقد اجتماعًا موسعًا لبناء خطة جديدة","score":1,"feedback_ar":"الخطة موجودة؛ الارتجال يضيع الأيام التي أعدت الخطة لتوفيرها.","then_ar":""},{"id":"wait","label":"أنتظر التقرير الشهري لعرضه","score":0,"feedback_ar":"القضية لا تنتظر دورة التقرير، خصوصًا على المسار الحرج.","then_ar":""},{"id":"shift","label":"أعدّل تاريخ التكامل في الجدول بهدوء","score":0,"feedback_ar":"تعديل خط الأساس بلا قرار يخفي الانحراف عمن يجب أن يقرر.","then_ar":""}]}]}$x$::jsonb
) on conflict (key) do nothing;

insert into leaders.lab_items (key, kind, dimension, chapter_key, sort, min_level, minutes, points, title_ar, summary_ar, spec) values (
  $x$benefits-map$x$, $x$tool$x$, $x$impact$x$, $x$ch2$x$, 1, $x$beginner$x$, 12, 40,
  $x$خريطة المنافع وسلسلة القيمة$x$,
  $x$رتّب سلسلة القيمة، وضع إنجازات برنامج حقيقي في حلقاتها، واكشف المخرج اليتيم الذي لا يغذي منفعة، ثم اكتب الأثر بلغة أمينة.$x$,
  $x${"story_ar":"برنامج ممول من مانح لثلاث سنوات، يدرّب الشباب الباحثين عن عمل ويربطهم بالشركات. يقترب موعد تقرير المانح، والفريق جمع قائمة طويلة بما \"حققه\" البرنامج.","role_ar":"مدير برنامج تأهيل الشباب للتوظيف في جمعية تنموية","closing_ar":"المخرجات تُسلَّم، لكن الاستثمار لا يُبرر إلا بالمنافع والأثر المستدام. وكل مخرج لا يغذي منفعة عبء يُراجع، وكل منفعة بلا مالك بعد الإغلاق منفعة ستضيع.","meters":[],"steps":[{"type":"order","title_ar":"سلسلة القيمة","prompt_ar":"رتّب حلقات السلسلة من الأقرب إلى المشروع إلى الأبعد عنه.","context_ar":"","why_ar":"المساءلة تصعد في السلسلة: نسلّم المخرجات، ثم يتغير السلوك، ثم يُقاس التحسن، ثم التحول الأوسع، ثم بقاؤه بعد خروجنا.","weight":1,"items":[{"id":"output","label":"المخرجات"},{"id":"outcome","label":"النتائج المباشرة"},{"id":"benefit","label":"المنافع"},{"id":"impact","label":"الأثر"},{"id":"sustain","label":"استدامة الأثر"}],"answer":["output","outcome","benefit","impact","sustain"]},{"type":"classify","title_ar":"أين يقع كل إنجاز؟","prompt_ar":"ضع كل بند من قائمة الفريق في حلقته.","context_ar":"","why_ar":"السؤال الفاصل: هل هذا ما سلّمناه، أم ما فعله الناس به، أم التحسن المقيس، أم التحول الأوسع، أم بقاؤه؟","weight":2,"bins":[{"id":"output","label":"مخرج"},{"id":"outcome","label":"نتيجة مباشرة"},{"id":"benefit","label":"منفعة"},{"id":"impact","label":"أثر"},{"id":"sustain","label":"استدامة"}],"items":[{"id":"grads","label":"تخريج 400 متدرب في البرمجة وخدمة العملاء","bin":"output"},{"id":"platform","label":"إطلاق منصة إلكترونية للتدريب","bin":"output"},{"id":"interviews","label":"التحاق 60% من الخريجين بمقابلات عمل خلال ثلاثة أشهر","bin":"outcome","note_ar":"تغير في السلوك والاستخدام، لكنه لم يصبح تحسنًا مقيسًا مقابل خط أساس بعد."},{"id":"employment","label":"ارتفاع نسبة توظيف الخريجين من 18% إلى 45% خلال سنة","bin":"benefit"},{"id":"unemployment","label":"انخفاض بطالة الشباب في الحي الذي يخدمه البرنامج","bin":"impact","note_ar":"تحول في المنظومة تسهم فيه عوامل كثيرة، فهو أثر لا منفعة."},{"id":"partners","label":"استمرار ال