ore":0,"feedback_ar":"الحذف يصنع تقريرًا ترويجيًا ويحرم اللجنة من قرار تحتاجه.","then_ar":""},{"id":"risk","label":"ننقلها إلى سجل المخاطر","score":1,"feedback_ar":"هي ليست احتمالًا؛ إنها نتيجة واقعة من التغيير نفسه.","then_ar":""}]}]}$x$::jsonb
