  $x${"story_ar":"سيوحد المشروع حجز المواعيد في ستة مستشفيات بنظام واحد مرتبط بالمنصة الوطنية. أمامك قائمة بأصحاب المصلحة كما وصفهم فريقك بعد أسبوعين من المقابلات.","role_ar":"قائد مشروع توحيد نظام المواعيد في تجمع صحي","closing_ar":"الخريطة ليست صورة ثابتة؛ تُحدَّث مع كل تغير في المواقف. وأخطر صاحب مصلحة من يملك النفوذ ولا يرى المشروع أولوية له، لأنه يعطل بصمت.","meters":[],"steps":[{"type":"plot","title_ar":"النفوذ والاهتمام","prompt_ar":"ضع كل صاحب مصلحة في مربعه.","context_ar":"","why_ar":"النفوذ قدرة على التأثير في قرار المشروع، والاهتمام درجة تأثر صاحب المصلحة به ومتابعته له.","weight":2,"size":2,"x_ar":["اهتمام منخفض","اهتمام مرتفع"],"y_ar":["نفوذ منخفض","نفوذ مرتفع"],"items":[{"id":"ceo","label":"الرئيس التنفيذي للتجمع: يملك قرار الميزانية، ويتابع المشروع شخصيًا لأنه من مستهدفات العام","x":1,"y":1},{"id":"cfo","label":"مدير الشؤون المالية: يعتمد كل صرف، ولا يهتم بتفاصيل المشروع","x":0,"y":1},{"id":"it","label":"مدير تقنية المعلومات بالوزارة: يعتمد الربط مع المنصة الوطنية، ويرى المشروع عبئًا إضافيًا","x":0,"y":1,"note_ar":"نفوذه حاسم لأن الربط بيده، واهتمامه منخفض: هذا هو المعارض الصامت المحتمل."},{"id":"clinics","label":"رؤساء أقسام العيادات: سيتغير عملهم اليومي كليًا، ولا يملكون قرار المشروع","x":1,"y":0},{"id":"patients","label":"ممثل المرضى في مجلس الأسرة: مهتم جدًا بزمن الانتظار، بلا سلطة","x":1,"y":0},{"id":"pr","label":"إدارة العلاقات العامة: تُبلغ بموعد الإطلاق فقط","x":0,"y":0}]},{"type":"match","title_ar":"استراتيجية كل مربع","prompt_ar":"اختر لكل مربع استراتيجية التعامل التي تناسبه.","context_ar":"","why_ar":"يُوجه جهد التواصل حيث النفوذ والاهتمام، ولكل مربع قناة وتكرار.","weight":1,"left":[{"id":"hh","label":"نفوذ مرتفع واهتمام مرتفع","match":"close"},{"id":"hl","label":"نفوذ مرتفع واهتمام منخفض","match":"satisfied"},{"id":"lh","label":"نفوذ منخفض واهتمام مرتفع","match":"informed"},{"id":"ll","label":"نفوذ منخفض واهتمام منخفض","match":"monitor"}],"right":[{"id":"close","label":"إدارة عن قرب: إشراك في القرارات ولقاءات منتظمة"},{"id":"satisfied","label":"إبقاء راضيًا: إيجاز مركز عند القرارات التي تمسه"},{"id":"informed","label":"إبقاء مطلعًا: تواصل منتظم وقنوات للرأي"},{"id":"monitor","label":"متابعة بجهد أدنى"}]},{"type":"choice","title_ar":"المعارض الصامت","prompt_ar":"مدير تقنية المعلومات بالوزارة لم يعترض علنًا، لكن طلب الربط معلق عنده منذ شهر، والمعلم القادم يعتمد عليه. ما خطوتك الأولى؟","context_ar":"","why_ar":"المعارض الصامت يُكسب بفهم ما يكلفه المشروع وعرض ما يخدمه، ويُصعّد أمره فقط بعد ذلك ومعه معلومات مكتملة.","weight":1,"options":[{"id":"meet","label":"أطلب لقاءً قصيرًا أفهم فيه ما يكلفه المشروع، وأعرض ما يخفف عبئه، كأن يتولى فريقي اختبارات الربط","score":4,"feedback_ar":"القيادة عبر الحدود تبدأ بفهم مصلحة الطرف الآخر ثم مقايضة تخدمه.","then_ar":""},{"id":"escalate","label":"أصعّد الأمر للرئيس التنفيذي فورًا","score":1,"feedback_ar":"التصعيد قبل محاولة الفهم قد ينجح مرة، لكنه يحول المعارض الصامت إلى معارض معلن.","then_ar":""},{"id":"letter","label":"أرسل خطابًا رسميًا بمهلة أسبوعين","score":1,"feedback_ar":"الخطاب يوثق، لكنه لا يعالج سبب التعطل.","then_ar":""},{"id":"wait","label":"أنتظر، فلعله مشغول","score":0,"feedback_ar":"الانتظار يترك المعلم القادم رهينة لأولويات غيرك.","then_ar":""}]}]}$x$::jsonb
