  $x$مصفوفة المسؤوليات والتفويض$x$,
  $x$ابنِ مصفوفة RACI من ميثاق حوكمة مكتوب، ثم اختر أسلوب القيادة المناسب لجاهزية كل عضو، وعالج قائدًا صار عنق زجاجة.$x$,
  $x${"story_ar":"في الاجتماع الأول للمرحلة الثانية سأل الراعي: من يقرر ماذا؟ ولم يجب أحد بالجواب نفسه. أمامك ميثاق الحوكمة المعتمد، ومهمتك أن تحوله إلى مصفوفة يفهمها الجميع.","role_ar":"مدير مشروع إطلاق خدمة \"رخصتي فورًا\"","closing_ar":"المصفوفة تمنع تعطل القرار وتنازع الصلاحية: لكل مهمة صاحب قرار واحد. والتفويض نقل لصلاحية القرار مع بقاء المساءلة، وأسلوبه يتبع جاهزية الشخص للمهمة لا شخصية القائد.","meters":[],"steps":[{"type":"matrix","title_ar":"من يقرر ماذا؟","prompt_ar":"املأ المصفوفة من الميثاق: R ينفذ، A صاحب القرار ويُسأل عن النتيجة، C يُستشار قبل القرار، I يُبلغ بعده. اترك الخانة فارغة إن لم يكن للدور علاقة.","context_ar":"ميثاق الحوكمة: الراعي يعتمد الميزانية، ويتلقى تقرير اللجنة الشهري ويعتمده، ويُسأل أمام الإدارة العليا عن تحقق المنافع. مدير المشروع يُسأل عن خطط التنفيذ والجودة، ويعد طلبات الميزانية والتقارير وملف القبول. قائد التطوير ينفذ العمل التقني ويُستشار في كل ما يمسه. مدير الخدمة يملك قرار قبول الخدمة للتشغيل، ويقيس منافعها بعد الإطلاق، ويُستشار في الميزانية وخطة الاختبار. ويُبلغ كل دور بنتيجة ما لم يشارك فيه، عدا خطة الاختبار فلا تُرفع للراعي.","why_ar":"لكل صف A واحد فقط، وإلا تنازعت الصلاحية أو ضاعت. وقبول الخدمة لمالكها التشغيلي لا لمدير المشروع، والمنفعة يُسأل عنها الراعي وينفذ قياسها مالكها.","weight":3,"rows":[{"id":"budget","label":"اعتماد ميزانية المرحلة الثانية"},{"id":"testplan","label":"إعداد خطة الاختبار"},{"id":"acceptance","label":"قبول الخدمة للتشغيل"},{"id":"report","label":"تقرير اللجنة الشهري"},{"id":"benefit","label":"قياس منفعة تقليص زمن الرخصة بعد ستة أشهر"}],"cols":[{"id":"sponsor","label":"الراعي"},{"id":"pm","label":"مدير المشروع"},{"id":"tech","label":"قائد التطوير"},{"id":"service","label":"مدير الخدمة"}],"values":[{"id":"R","label":"R ينفذ"},{"id":"A","label":"A يقرر"},{"id":"C","label":"C يُستشار"},{"id":"I","label":"I يُبلغ"}],"expected":{"budget":{"sponsor":"A","pm":"R","tech":"I","service":"C"},"testplan":{"pm":"A","tech":"R","service":"C"},"acceptance":{"sponsor":"I","pm":"R","tech":"C","service":"A"},"report":{"sponsor":"A","pm":"R","tech":"C","service":"I"},"benefit":{"sponsor":"A","pm":"C","tech":"I","service":"R"}},"once_per_row":["A"]},{"type":"match","title_ar":"أسلوب القيادة لكل عضو","prompt_ar":"اختر لكل عضو الأسلوب الذي تناسبه جاهزيته لمهمة ربط الخدمة بالأنظمة الحكومية.","context_ar":"","why_ar":"الجاهزية كفاءة والتزام: كفاءة منخفضة وحماس عالٍ يحتاجان توجيهًا، وكفاءة عالية وثقة عالية تستحقان تفويضًا.","weight":1,"left":[{"id":"new","label":"مهندسة انضمت قبل أسبوعين، متحمسة، ولم تجرب الربط من قبل","match":"direct"},{"id":"stuck","label":"مطور جرب المهمة مرتين وتعثر، وفقد حماسه","match":"coach"},{"id":"hesitant","label":"محلل متمكن من المهمة، لكنه متردد في القرار وحده بعد خطأ سابق","match":"support"},{"id":"expert","label":"قائد اختبار نفذ المهمة مرات كثيرة بنجاح ويطلب مساحة","match":"delegate"}],"right":[{"id":"direct","label":"توجيه"},{"id":"coach","label":"تدريب"},{"id":"support","label":"مساندة"},{"id":"delegate","label":"تفويض"}]},{"type":"choice","title_ar":"عنق الزجاجة","prompt_ar":"كل قرار صغير في المشروع ينتظر توقيعك، والفريق يقول إنك عنق الزجاجة. ما خطوتك الأولى؟","context_ar":"","why_ar":"التفويض نقل صلاحية القرار مع بقاء المساءلة، ويُكتب في ميثاق: ما فُوض لمن وبأي حدود.","weight":1,"options":[{"id":"charter","label":"أكتب مع الفريق ميثاق تفويض: ما يقرره كل عضو، وحدوده، ومتى يصعد إلي","score":4,"feedback_ar":"الميثاق ينقل القرار مع حدوده، فلا تخلٍّ ولا وصاية.","then_ar":""},{"id":"hours","label":"أعمل ساعات أطول لأنجز التواقيع أسرع","score":0,"feedback_ar":"يعالج العرض ويبقي القرار متركزًا عندك.","then_ar":""},{"id":"all","label":"أفوض كل القرارات دفعة واحدة","score":1,"feedback_ar":"تفويض بلا حدود ولا جاهزية تخلٍّ قد يرتد أخطاءً مكلفة.","then_ar":""},{"id":"assistant","label":"أطلب مساعدًا إداريًا يرتب لي التواقيع","score":1,"feedback_ar":"ينظم الطابور ولا يقصره.","then_ar":""}]}]}$x$::jsonb
) on conflict (key) do nothing;

insert into leaders.lab_items (key, kind, dimension, chapter_key, sort, min_level, minutes, points, title_ar, summary_ar, spec) values (
  $x$red-gate$x$, $x$scenario$x$, $x$milestone$x$, $x$ch4$x$, 3, $x$beginner$x$, 20, 60,
  $x$البوابة الحمراء$x$,
  $x$بوابة اعتماد التشغيل التجريبي بعد أسبوع، والاختبارات لم تكتمل، والراعي يريد إطلاقًا أمام الوزير. كل قرار يحرك مؤشرات المشروع.$x$,
  $x${"story_ar":"المشروع في شهره السادس من عشرة. بوابة اعتماد التشغيل التجريبي بعد أسبوع، ونجح 70% فقط من اختبارات التكامل مقابل معيار قبول 95%. والراعي أعلن للإدارة العليا أن الإطلاق سيكون في حفل وطني بعد ستة أسابيع بحضور الوزير.","role_ar":"مدير مشروع مركز الخدمات الرقمي","closing_ar":"البوابة ليست موعدًا يُعبر، بل قرار: استمرار أو تصحيح أو إيقاف، ومعه البديل. والتقرير الذي يقول الحقيقة مبكرًا يكلف ثقة يوم، والتقرير الأخضر المجامل يكلف ثقة المشروع كله.","meters":[{"id":"time","label":"الوقت","start":60},{"id":"budget","label":"الميزانية","start":65},{"id":"trust","label":"ثقة الراعي","start":70},{"id":"team","label":"طاقة الفريق","start":60},{"id":"evidence","label":"قوة الدليل","start":50}],"steps":[{"type":"choice","title_ar":"التقرير الأسبوعي","prompt_ar":"قبل البوابة بأسبوع طلب منك الراعي تقريرًا \"أخضر\" لأن الوزير سيحضر الإطلاق. ماذا تكتب؟","context_ar":"","why_ar":"التقرير أداة قرار لا أداة طمأنة؛ قيمته في الانحراف المقيس والقرار المطلوب.","weight":1,"id":"report","options":[{"id":"green","label":"أكتبه أخضر وأعالج المشكلات قبل البوابة","score":0,"feedback_ar":"الأخضر المجامل يشتري هدوء أسبوع ويؤجل الانفجار إلى لحظة أغلى.","then_ar":"مر الأسبوع بهدوء، لكن قائد التطوير سألك أمام الفريق: كيف يكون أخضر واختبار التكامل عند 70%؟","effects":{"trust":10,"evidence":-25,"team":-10}},{"id":"true","label":"أكتبه بحالته الحقيقية: أصفر بانحراف مقيس عن معيار القبول، ومعه خيارات القرار","score":4,"feedback_ar":"حقيقة مبكرة ومعها خيارات: هذا ما يحتاجه صاحب القرار.","then_ar":"اتصل بك الراعي منزعجًا، ثم طلب أن تعرض الخيارات في البوابة بوضوح.","effects":{"trust":-5,"evidence":20}},{"id":"delay","label":"أؤجل التقرير حتى تكتمل الاختبارات","score":1,"feedback_ar":"الصمت يُقرأ أسوأ من الخبر السيئ.","then_ar":"سأل الراعي عن التقرير مرتين، وبدأ يسمع الأخبار من غيرك.","effects":{"trust":-15,"time":-5}}]},{"type":"classify","title_ar":"ورقة القرار","prompt_ar":"جهّز ورقة البوابة من صفحة واحدة: ما الذي يدخلها؟","context_ar":"","why_ar":"الورقة التي تكفي المجلس ليقرر دون عرض شفهي: الحالة مقابل خط الأساس، والمخاطر، ومبرر الاستمرار، والخيارات.","weight":1,"id":"paper","bins":[{"id":"in","label":"يدخل ورقة القرار"},{"id":"out","label":"لا يلزم القرار"}],"items":[{"id":"variance","label":"الانحراف عن خط الأساس بالأيام والتكلفة","bin":"in"},{"id":"tests","label":"نتيجة اختبار التكامل 70% مقابل معيار القبول 95%","bin":"in"},{"id":"risks","label":"المخاطر المفتوحة وأثرها على الإطلاق","bin":"in"},{"id":"case","label":"مبرر الاستمرار بلغة القيمة","bin":"in"},{"id":"options","label":"ثلاثة خيارات، وقرار مقترح ومعه البديل","bin":"in"},{"id":"meetings","label":"قائمة بكل الاجتماعات المنعقدة في المرحلة","bin":"out"},{"id":"bugs","label":"تفاصيل كل خلل برمجي مفتوح","bin":"out","note_ar":"يكفي أثر الخلل على القرار؛ التفاصيل في ملحق لمن يطلبها."},{"id":"thanks","label":"شكر الفريق على جهده","bin":"out"}]},{"type":"choice","title_ar":"قرار البوابة","prompt_ar":"في البوابة، اللجنة تنظر إليك. ما القرار الذي تقترحه؟","context_ar":"","why_ar":"البوابة معلم إلزامي لا يُعبر إلا بقرار رسمي، والقرار الجيد يوازن القيمة والمخاطر ويأتي ببديل.","weight":2,"id":"gate","options":[{"id":"go","label":"استمرار: تشغيل تجريبي كامل لكل الخدمات في موعد الحفل","score":1,"feedback_ar":"عبور بوابة بمعيار قبول لم يتحقق قصور ذاتي لا قرار.","then_ar":"صفق الراعي، وضغط الفريق ليلًا ونهارًا لستة أسابيع.","effects":{"time":10,"trust":10,"evidence":-15,"team":-15},"next":"crisis"},{"id":"adjust","label":"تصحيح: تشغيل تجريبي لخدمتين ناضجتين في موعد الحفل، وبقية الخدمات بعد أربعة أسابيع بعد اجتياز معيار القبول","score":4,"feedback_ar":"قرار يحفظ موعد الراعي ويحمي الجودة، ومعه شرط واضح للمرحلة التالية.","then_ar":"اعتمدت اللجنة القرار بشرط مراجعة عند المعلم التالي، وسيظهر الوزير مع خدمتين تعملان فعلًا.","effects":{"time":-5,"trust":5,"evidence":15,"team":5},"next":"pilot"},{"id":"stop","label":"إيقاف: إعادة المشروع إلى التخطيط","score":1,"feedback_ar":"الإيقاف خيار مشروع، لكن الانحراف هنا قابل للتصحيح ومبرر الاستمرار قائم.","then_ar":"رفضت اللجنة الإيقاف، وطلبت خطة تصحيح خلال أسبوع.","effects":{"time":-25,"budget":-15,"trust":-20,"team":-10},"next":"pilot"}]},{"type":"choice","title_ar":"أمام الإعلام","prompt_ar":"في يوم الحفل تعطلت خدمة الرخص ساعتين أمام الإعلام. ماذا تفعل؟","context_ar":"","why_ar":"حين يقع ما حذرت منه، تُفعّل الاستجابة المعدة ويُقال الواقع كما هو.","weight":1,"id":"crisis","next":"close","options":[{"id":"own","label":"أعلن الحقيقة، وأفعّل خطة الطوارئ، وأقصر التشغيل على الخدمات المستقرة","score":3,"feedback_ar":"المساءلة العلنية والتقليص المدروس يحفظان ما بقي من الثقة.","then_ar":"استعادت الخدمة عملها، وقبل الراعي التقليص بعد أن رأى البيانات.","effects":{"trust":-5,"evidence":10,"team":5}},{"id":"blame","label":"أوضح للإعلام أن الخلل من المورد","score":0,"feedback_ar":"لوم الشريك علنًا يكسر العلاقة التي تحتاجها للإصلاح.","then_ar":"غضب المورد، وتوقف تعاونه أسبوعًا.","effects":{"trust":-15,"team":-10}},{"id":"silent","label":"أصمت وأصلح بهدوء","score":1,"feedback_ar":"الصمت في الأزمة يترك غيرك يكتب القصة.","then_ar":"عرف الراعي التفاصيل من الصحف.","effects":{"trust":-10}}]},{"type":"allocate","title_ar":"وقت الفريق","prompt_ar":"أمامك 100 يوم عمل من وقت فريق التطوير للأسابيع الأربعة القادمة. وزعها على البنود.","context_ar":"","why_ar":"معيار القبول هو شرط القرار، فإصلاح التكامل أولًا، ثم دعم ما أُطلق، ثم نقل المعرفة الذي يُنسى عادة حتى يفوت أوانه.","weight":1,"id":"pilot","items":[{"id":"fix","label":"إصلاح أخطاء التكامل الحرجة"},{"id":"support","label":"دعم التشغيل التجريبي للخدمتين"},{"id":"handover","label":"توثيق ونقل المعرفة لفريق التشغيل"},{"id":"ui","label":"تحسين واجهة خدمات لم تُطلق بعد"}],"total":100,"unit_ar":"يوم","ideal":{"fix":50,"support":30,"handover":15,"ui":5},"tol":10},{"type":"order","title_ar":"بعد القرار","prompt_ar":"رتّب خطوات ما بعد قرار البوابة.","context_ar":"","why_ar":"القرار الموثق أولًا، ثم الخطة التي تعكسه، ثم إبلاغ من يتأثر به، ثم التحقق من شروطه.","weight":1,"id":"close","items":[{"id":"log","label":"توثيق القرار ومبرره وشروطه في سجل القرارات"},{"id":"baseline","label":"تحديث خط الأساس بعد اعتماد التغيير"},{"id":"tell","label":"إبلاغ أصحاب المصلحة بالقرار وأثره عليهم"},{"id":"follow","label":"متابعة شروط القرار عند المعلم التالي"}],"answer":["log","baseline","tell","follow"]}]}$x$::jsonb
) on conflict (key) do nothing;

insert into leaders.lab_items (key, kind, dimension, chapter_key, sort, min_level, minutes, points, title_ar, summary_ar, spec) values (
  $x$hard-week$x$, $x$scenario$x$, $x$leadership$x$, $x$ch2$x$, 3, $x$beginner$x$, 20, 60,
  $x$الأسبوع الصعب$x$,
  $x$توجيه عاجل فيه خلل، وإدارة موازية لا سلطة لك عليها، وأولويات تتزاحم. أسبوع واحد تختبر فيه الاستجابة المنضبطة من التلقي إلى الإغلاق.$x$,
  $x${"story_ar":"صباح الأحد. وصلتك رسالة صوتية من الراعي، وعلى مكتبك طلب معلق لدى إدارة تقنية المعلومات، وخلاف بين عضوين في فريقك يعطل التكامل. والأسبوع ينتهي بعرض أمام وكيل الوزارة.","role_ar":"قائد برنامج التحول الرقمي في جهة حكومية","closing_ar":"السرعة الحقيقية تُكسب في التلقي والتفهم لا في ضغط التحرك. والاعتراض المسبب مع البديل جزء من الاستجابة لا خروج عليها، والإنجاز الذي لا يعود خبره لصاحب الأمر يُحسب تأخيرًا.","meters":[{"id":"time","label":"الوقت","start":55},{"id":"trust","label":"ثقة الراعي","start":60},{"id":"team","label":"طاقة الفريق","start":60},{"id":"peers","label":"ثقة النظراء","start":50}],"steps":[{"type":"choice","title_ar":"الرسالة الصوتية","prompt_ar":"رسالة الراعي: \"جهّز عرضًا عن المشروع للوكيل يوم الثلاثاء\". ماذا تفعل أولًا؟","context_ar":"","why_ar":"التلقي استلام للمقصود لا للكلمات، وإعادة صياغة التوجيه للتحقق أول سلوك في الاستجابة المنضبطة.","weight":1,"id":"receive","options":[{"id":"build","label":"أبدأ فورًا بعرض شامل عن المشروع","score":1,"feedback_ar":"تحرك قبل التفهم: طاقة عالية في اتجاه لم يُطلب.","then_ar":"يوم الاثنين، بعد أربعين شريحة، عرفت أن الوكيل يريد شيئًا آخر تمامًا.","effects":{"time":-15,"team":-10}},{"id":"confirm","label":"أقر بالاستلام وأعيد صياغة المقصود: \"أفهم أن المطلوب حالة المشروع وما نحتاجه من الوكيل في عشر دقائق، صحيح؟\"","score":4,"feedback_ar":"إقرار الاستلام وإعادة الصياغة يوفران أيامًا من العمل الضائع.","then_ar":"رد الراعي: \"بالضبط، وركّز على المعالم الثلاثة المتأخرة وما نحتاجه منه لحلها\".","effects":{"trust":10,"time":10}},{"id":"forward","label":"أحيل الطلب لأحد أعضاء الفريق كما هو","score":0,"feedback_ar":"التفويض قبل التفهم ينقل الغموض إلى غيرك.","then_ar":"جاءك عضو الفريق بعد يومين بأسئلة لا تعرف إجابتها.","effects":{"trust":-10,"team":-5}}]},{"type":"order","title_ar":"سلسلة الاستجابة","prompt_ar":"رتّب مراحل الاستجابة المنضبطة التي ستمضي فيها هذا الأسبوع.","context_ar":"","why_ar":"السرعة بلا تفهم تهور، والتفهم بلا تحرك تعطيل؛ الجدارة في المسار كاملًا.","weight":1,"id":"chain","items":[{"id":"